cd /workspace && python3 -c "import docx, lxml; print('docx', docx.__version__)" 2>&1; echo "---PLACEHOLDERS---"; python3 -c "
import docx, re
d=docx.Document('inputs/offer_letter_template.docx')
def paras(doc):
    for p in doc.paragraphs: yield p
    for t in doc.tables:
        for r in t.rows:
            for c in r.cells:
                for p in c.paragraphs: yield p
                for nt in c.tables:
                    for rr in nt.rows:
                        for cc in rr.cells:
                            yield from cc.paragraphs
    for s in doc.sections:
        for part in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
            if part is None: continue
            for p in part.paragraphs: yield p
seen=set()
for p in paras(d):
    for m in re.findall(r'\{\{[^}]*\}\}', ''.join(r.text for r in p.runs)):
        seen.add(m)
import pprint; pprint.pprint(sorted(seen))
"

cd /workspace && python3 -c "
import docx, re
d=docx.Document('output/offer_letter_filled.docx')
def paras(doc):
    for p in doc.paragraphs: yield p
    for t in doc.tables:
        for r in t.rows:
            for c in r.cells:
                for p in c.paragraphs: yield p
                for nt in c.tables:
                    for rr in nt.rows:
                        for cc in rr.cells:
                            yield from cc.paragraphs
    for s in doc.sections:
        for part in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
            if part is None: continue
            for p in part.paragraphs: yield p
left=set()
for p in paras(d):
    txt=''.join(r.text for r in p.runs)
